"use client";

import React, { useState } from "react";
import { 
  Calendar, Sun, Coffee, ArrowRight, 
  MapPin, Clock, Briefcase, ChevronRight,
  Plane, Sparkles
} from "lucide-react";

/* --- 1. SMART DATA (With "Opportunity" Logic) --- */
const holidays = [
  { 
    name: "Republic Day", 
    date: "Jan 26, 2026", 
    day: "Monday", 
    type: "National", 
    tag: "Long Weekend 🏖️", // AI Logic: It's a Monday
    opportunity: null 
  },
  { 
    name: "Holi", 
    date: "Mar 3, 2026", 
    day: "Tuesday", 
    type: "Public", 
    tag: null,
    opportunity: "Take Mon off for 4-day break" // AI Logic: Suggest Bridge Day
  },
  { 
    name: "Good Friday", 
    date: "Apr 3, 2026", 
    day: "Friday", 
    type: "Public", 
    tag: "Long Weekend 🏖️",
    opportunity: null
  },
  { 
    name: "Independence Day", 
    date: "Aug 15, 2026", 
    day: "Saturday", 
    type: "National", 
    tag: "Weekend Overlap",
    opportunity: "Comp-off applicable"
  },
  { 
    name: "Diwali", 
    date: "Nov 8, 2026", 
    day: "Sunday", 
    type: "Public", 
    tag: "Weekend Overlap",
    opportunity: null
  },
];

export default function IntegratedHolidayHub() {
  const [filter, setFilter] = useState("Upcoming");

  return (
    <div className="min-h-screen bg-[#F8F9FB] dark:bg-[#050505] p-6 lg:p-10 font-sans text-slate-900 dark:text-slate-100">
      
      {/* 1. THE "TIME OFF" DASHBOARD (HUD) */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-10">
        
        {/* Hero Card: Next Holiday */}
        <div className="lg:col-span-2 bg-slate-900 dark:bg-brand-600 rounded-[2.5rem] p-8 text-white relative overflow-hidden group">
          <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2" />
          <div className="relative z-10 flex flex-col h-full justify-between">
            <div>
               <div className="flex items-center gap-2 mb-2">
                 <span className="px-3 py-1 bg-white/10 rounded-full text-[10px] font-black uppercase tracking-widest backdrop-blur-md">Upcoming in 2 Days</span>
               </div>
               <h2 className="text-4xl font-black italic tracking-tighter uppercase">Republic Day</h2>
               <p className="text-sm text-slate-300 mt-2 font-medium">National Observance • All Offices Closed</p>
            </div>
            <div className="mt-8 flex items-center gap-4">
               <div className="flex flex-col">
                  <span className="text-[10px] font-black uppercase text-slate-400">Date</span>
                  <span className="text-xl font-black">Jan 26</span>
               </div>
               <div className="w-[1px] h-8 bg-white/20" />
               <div className="flex flex-col">
                  <span className="text-[10px] font-black uppercase text-slate-400">Day</span>
                  <span className="text-xl font-black">Monday</span>
               </div>
               <button className="ml-auto bg-white text-slate-900 px-6 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest hover:scale-105 transition-transform flex items-center gap-2">
                  Plan Absence <ArrowRight size={14} />
               </button>
            </div>
          </div>
        </div>

        {/* Stats / Quick Actions */}
        <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] p-8 border border-slate-100 dark:border-slate-800 flex flex-col justify-between shadow-sm">
           <div>
             <h3 className="text-lg font-black tracking-tight uppercase">My Balance</h3>
             <div className="mt-4 flex items-baseline gap-1">
                <span className="text-5xl font-black text-brand-600">12</span>
                <span className="text-sm font-bold text-slate-400">/ 18 Days</span>
             </div>
             <p className="text-xs text-slate-400 mt-2">Annual Leave Remaining</p>
           </div>
           <button className="w-full mt-6 flex items-center justify-between p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl hover:bg-brand-50 dark:hover:bg-brand-500/10 transition-colors group">
              <span className="text-[10px] font-black uppercase tracking-widest text-slate-500 group-hover:text-brand-600">Request Time Off</span>
              <div className="w-8 h-8 bg-white dark:bg-slate-700 rounded-full flex items-center justify-center text-slate-400 group-hover:text-white group-hover:bg-brand-500 transition-all">
                <PlusIcon />
              </div>
           </button>
        </div>
      </div>

      {/* 2. INTELLIGENT LIST */}
      <div className="flex items-center justify-between mb-6">
        <h3 className="text-xl font-black tracking-tight uppercase italic">2026 Calendar</h3>
        <div className="flex bg-white dark:bg-slate-900 p-1 rounded-xl border border-slate-100 dark:border-slate-800">
           {['Upcoming', 'Past', 'Optional'].map(t => (
             <button 
               key={t}
               onClick={() => setFilter(t)}
               className={`px-4 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${filter === t ? 'bg-slate-900 text-white dark:bg-brand-600' : 'text-slate-400 hover:text-slate-900'}`}
             >
               {t}
             </button>
           ))}
        </div>
      </div>

      <div className="space-y-4">
        {holidays.map((holiday, idx) => (
          <div 
            key={idx}
            className="group relative bg-white dark:bg-slate-900 rounded-[2rem] p-1 border border-slate-100 dark:border-slate-800 hover:border-brand-500/30 transition-all hover:shadow-xl hover:shadow-brand-500/5"
          >
            <div className="flex flex-col md:flex-row items-center gap-6 p-5">
              
              {/* Date Block */}
              <div className="flex-shrink-0 w-full md:w-20 h-20 bg-slate-50 dark:bg-slate-800 rounded-[1.5rem] flex flex-col items-center justify-center border border-slate-100 dark:border-slate-700/50 group-hover:scale-105 transition-transform">
                 <span className="text-[10px] font-black uppercase text-slate-400">{holiday.date.split(' ')[0]}</span>
                 <span className="text-2xl font-black text-slate-900 dark:text-white">{holiday.date.split(' ')[1].replace(',','')}</span>
              </div>

              {/* Main Info */}
              <div className="flex-1 text-center md:text-left">
                 <div className="flex flex-wrap items-center justify-center md:justify-start gap-2 mb-1">
                    <span className={`px-2 py-0.5 rounded-md text-[9px] font-black uppercase tracking-widest ${holiday.type === 'National' ? 'bg-purple-100 text-purple-600 dark:bg-purple-500/10 dark:text-purple-400' : 'bg-emerald-100 text-emerald-600 dark:bg-emerald-500/10 dark:text-emerald-400'}`}>
                      {holiday.type}
                    </span>
                    {holiday.tag && (
                      <span className="flex items-center gap-1 px-2 py-0.5 rounded-md text-[9px] font-black uppercase tracking-widest bg-amber-100 text-amber-700 dark:bg-amber-500/10 dark:text-amber-500">
                        <Sparkles size={10} /> {holiday.tag}
                      </span>
                    )}
                 </div>
                 <h4 className="text-lg font-black tracking-tight text-slate-900 dark:text-white uppercase group-hover:text-brand-600 transition-colors">{holiday.name}</h4>
                 <div className="flex items-center justify-center md:justify-start gap-4 mt-1">
                    <span className="text-xs font-bold text-slate-400">{holiday.day}</span>
                    {holiday.opportunity && (
                      <span className="hidden md:flex items-center gap-1 text-[10px] font-bold text-brand-500 bg-brand-50 dark:bg-brand-500/10 px-2 rounded-full">
                        <Briefcase size={10} /> Tip: {holiday.opportunity}
                      </span>
                    )}
                 </div>
              </div>

              {/* Action Area */}
              <div className="flex-shrink-0 w-full md:w-auto">
                 <button className="w-full md:w-auto flex items-center justify-center gap-2 bg-slate-900 dark:bg-white text-white dark:text-slate-900 px-6 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-brand-600 dark:hover:bg-brand-400 transition-all opacity-0 group-hover:opacity-100 translate-x-4 group-hover:translate-x-0">
                    <Plane size={14} /> Extend Leave
                 </button>
              </div>

            </div>
          </div>
        ))}
      </div>

    </div>
  );
}

const PlusIcon = () => (
  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="4" strokeLinecap="round" strokeLinejoin="round">
    <path d="M12 5v14M5 12h14"/>
  </svg>
)